    # Minimum number of seconds between two throttled (non-forced) status updates.
    _UPDATE_INTERVAL = 10.0
    # Number of seconds a cached token is considered fresh before being re-read from disk.
    _TOKEN_TTL = 60.0
    # Timeout, in seconds, applied to each request sent to the server.
    _REQUEST_TIMEOUT = 10.0

    def __init__(self):
        self._initialized = False
        self._metrics = {}
        self._start_time = None
        self._last_update_time = 0.0
        self._cached_token = None
        self._token_read_time = 0.0
        self._ssl_context = None
        self._ssl_context_initialized = False

    def on_train_begin(self, args, state, control, **kwargs):
        if not state.is_world_process_zero:
            return
        self._initialized = True
        self._start_time = time.monotonic()
        self._update_status(progress_percent=0, force=True)

    def on_step_end(self, args, state, control, **kwargs):
        if not self._initialized:
            return

        if state.max_steps and state.max_steps > 0:
            progress_percent = int(100 * state.global_step / state.max_steps)
        else:
            progress_percent = 0
        # The completion of the training run is reported separately in `on_train_end`, so cap in-progress updates.
        progress_percent = min(progress_percent, 99)

        estimated_time_remaining = None
        if (
            self._start_time is not None
            and state.global_step > 0
            and state.max_steps
            and state.max_steps > 0
        ):
            elapsed = time.monotonic() - self._start_time
            time_per_step = elapsed / state.global_step
            estimated_time_remaining = time_per_step * (state.max_steps - state.global_step)

        self._update_status(
            progress_percent,
            estimated_time_remaining=estimated_time_remaining,
            metrics=self._metrics,
        )

    def on_log(self, args, state, control, logs=None, **kwargs):
        if not logs:
            return
        for key, value in logs.items():
            # Store only numeric values; booleans are excluded even though they are a subclass of `int`.
            if isinstance(value, numbers.Number) and not isinstance(value, bool):
                self._metrics[key] = value

    def on_train_end(self, args, state, control, **kwargs):
        self._update_status(progress_percent=100, estimated_time_remaining=0, force=True)

    def _update_status(self, progress_percent, force=False, estimated_time_remaining=None, metrics=None):
        server_url = os.environ.get("KUBEFLOW_TRAINER_SERVER_URL")
        if not server_url:
            return False

        now = time.monotonic()
        if not force and (now - self._last_update_time) < self._UPDATE_INTERVAL:
            return False

        payload = {"progress_percent": progress_percent}
        if estimated_time_remaining is not None:
            payload["estimated_time_remaining"] = estimated_time_remaining
        if metrics:
            payload["metrics"] = dict(metrics)

        data = json.dumps(payload).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        token = self._get_token()
        if token:
            headers["Authorization"] = f"Bearer {token}"

        request = urllib.request.Request(server_url, data=data, headers=headers, method="POST")

        if not self._ssl_context_initialized:
            self._ssl_context = self._build_ssl_context(server_url)
            self._ssl_context_initialized = True

        try:
            with urllib.request.urlopen(request, timeout=self._REQUEST_TIMEOUT, context=self._ssl_context):
                pass
        except Exception as e:
            logger.warning(f"Failed to report training status to the Kubeflow server: {e}")
            return False

        self._last_update_time = now
        return True

    def _build_ssl_context(self, server_url):
        if not server_url.lower().startswith("https"):
            return None
        ca_cert = os.environ.get("KUBEFLOW_TRAINER_SERVER_CA_CERT")
        if ca_cert and os.path.exists(ca_cert):
            return ssl.create_default_context(cafile=ca_cert)
        return ssl.create_default_context()

    def _get_token(self):
        token_path = os.environ.get("KUBEFLOW_TRAINER_SERVER_TOKEN")
        if not token_path:
            return None

        now = time.monotonic()
        if self._cached_token is not None and (now - self._token_read_time) < self._TOKEN_TTL:
            return self._cached_token

        try:
            with open(token_path) as f:
                self._cached_token = f.read().strip()
        except OSError as e:
            logger.warning(f"Failed to read the Kubeflow server token from {token_path}: {e}")
            return self._cached_token

        self._token_read_time = now
        return self._cached_token


